"INSERT INTO tracking_movement " +
"(last_status, rfid_user, nama, bagian, line, rfid_garment, id_garment, style, item, buyer, wo, color, size) " +

"SELECT 'OUTPUT_SEWING', u.rfid_user, u.nama, u.bagian, u.line, " +
