const TIMEOUT = 15000; // 15 detik

// ================= CONTEXT =================
let status        = context.get("status") || "UNKNOWN";
let lastSeen      = context.get("lastSeen") || null;
let deviceLine    = context.get("line") || null;   // line aktif device
let userLine      = flow.get("line1");            // line user login
let ip            = flow.get("ip1");

let hangTimer     = context.get("hangTimer");
let offlineTimer  = context.get("offlineTimer");

// ================= UTILITY =================
function nowISO() {
    return new Date(Date.now() + 7 * 60 * 60 * 1000).toISOString();
}

// ================= FORCE OFFLINE ON LINE SWITCH =================
if (
    deviceLine &&
    userLine &&
    deviceLine !== userLine &&
    status !== "OFFLINE"
) {
    // 1. OFFLINE-kan line lama
    node.send({
        payload: {
            line: deviceLine,
            status: "OFFLINE",
            lastSeen: lastSeen,
            ip: ip,
        }
    });

    // 2. Clear timers lama
    if (hangTimer) clearTimeout(hangTimer);
    if (offlineTimer) clearTimeout(offlineTimer);

    // 3. Switch ownership
    deviceLine = userLine;
    context.set("line", deviceLine);
    status = "UNKNOWN";
    context.set("status", status);
}

// ================= HANDLE ONLINE =================
if (msg.payload === 1 || msg.payload === "1") {

    status   = "ONLINE";
    lastSeen = nowISO();

    // Lock line jika belum ada
    if (!deviceLine && userLine) {
        deviceLine = userLine;
        context.set("line", deviceLine);
    }

    // Reset timers
    if (hangTimer) clearTimeout(hangTimer);
    if (offlineTimer) clearTimeout(offlineTimer);

    // Timer HANG
    hangTimer = setTimeout(() => {
        context.set("status", "HANG");
        node.send({
            payload: {
                line: deviceLine,
                status: "HANG",
                lastSeen: context.get("lastSeen"),
                ip: ip
            }
        });
    }, TIMEOUT);

    // Save context
    context.set("status", status);
    context.set("lastSeen", lastSeen);
    context.set("hangTimer", hangTimer);
    context.set("offlineTimer", null);

    // Output ONLINE
    msg.payload = {
        line: deviceLine,
        status: status,
        lastSeen: lastSeen,
        ip: ip
    };

    return msg;
}

// ================= HANDLE SILENT =================
if (msg.payload === 0 || msg.payload === "0") {

    if (hangTimer) clearTimeout(hangTimer);
    if (offlineTimer) clearTimeout(offlineTimer);

    offlineTimer = setTimeout(() => {
        status = "OFFLINE";

        context.set("status", status);
        context.set("line", null); // release ownership

        node.send({
            payload: {
                line: deviceLine,
                status: status,
                lastSeen: context.get("lastSeen"),
                ip: ip
            }
        });
    }, TIMEOUT);

    context.set("offlineTimer", offlineTimer);
    return null;
}

return null;

