        context.set("line", null); // release ownership

        node.send({
            payload: {
                line: deviceLine,
                status: status,
                lastSeen: context.get("lastSeen"),
                ip: ip
            }
        });
    }, TIMEOUT);

    context.set("offlineTimer", offlineTimer);
    return null;
}

